<template>
  <q-page class="inventory-page">
    <header class="page-head">
      <div><div class="eyebrow">{{ t('inventory.eyebrow') }}</div><h1>{{ t('inventory.title') }}</h1><p>{{ t('inventory.subtitle') }}</p></div>
      <div class="actions"><q-btn outline no-caps icon="download" :label="t('inventory.download')" @click="exportReport"/><q-btn unelevated no-caps color="primary" icon="add" :label="t('inventory.addOperation')" @click="openMovement"/></div>
    </header>

    <section class="metrics">
      <article v-for="card in metricCards" :key="card.label" class="metric" :class="card.tone"><div><span>{{ card.label }}</span><q-icon :name="card.icon"/></div><strong>{{ card.value }}</strong><small><q-icon :name="card.subIcon"/> {{ card.sub }}</small></article>
    </section>

    <div class="tabs"><q-tabs v-model="tab" dense align="left" active-color="primary" indicator-color="primary"><q-tab name="overview" icon="space_dashboard" :label="t('inventory.overview')"/><q-tab name="products" icon="inventory_2" :label="t('inventory.products')"/><q-tab name="operations" icon="swap_vert" :label="t('inventory.operations')"/><q-tab name="reports" icon="analytics" :label="t('inventory.reports')"/></q-tabs></div>
    <q-tab-panels v-model="tab" animated class="panels">
      <q-tab-panel name="overview" class="q-pa-none">
        <div class="two-col"><q-card flat class="panel"><div class="panel-head"><div><h2>{{ t('inventory.salesDynamics') }}</h2><span>{{ t('inventory.lastSevenDays') }}</span></div><q-chip color="blue-1" text-color="primary" icon="calendar_today">{{ monthName }}</q-chip></div><div class="chart"><div v-for="day in chart" :key="day.date" class="bar-col"><small>{{ compact(day.value) }}</small><div class="bar-track"><i :style="{height: `${day.percent}%`}"/></div><em>{{ day.label }}</em></div></div></q-card><q-card flat class="panel"><div class="panel-head"><div><h2>{{ t('inventory.categories') }}</h2><span>{{ t('inventory.warehouseDistribution') }}</span></div><q-icon name="donut_large" color="primary" size="24px"/></div><div v-for="item in categoryStats" :key="item.name" class="category"><div><span><i :style="{background:item.color}"/>{{ item.name }}</span><b>{{ item.percent }}%</b></div><q-linear-progress rounded :value="item.percent / 100" :color="item.qColor" track-color="grey-3" size="7px"/></div><div v-if="!categoryStats.length" class="empty">{{ t('inventory.noData') }}</div></q-card></div>
        <div class="two-col lower"><q-card flat class="panel"><div class="panel-head"><div><h2>{{ t('inventory.latestOperations') }}</h2><span>{{ t('inventory.latestActions') }}</span></div><q-btn flat no-caps color="primary" :label="t('inventory.all')" @click="tab='operations'"/></div><div v-for="item in recent" :key="item.id" class="operation"><div class="op-icon" :class="item.type"><q-icon :name="item.type==='in' ? 'south_west' : 'north_east'"/></div><div class="op-name"><b>{{ productName(item.productId) }}</b><span>{{ item.note || (item.type==='in' ? t('inventory.receivedProduct') : t('inventory.saleOutflow')) }}</span></div><b class="op-qty" :class="item.type">{{ item.type==='in' ? '+' : '-' }}{{ item.quantity }} {{ unit(item.productId) }}</b><strong>{{ money(item.quantity * item.price) }}<small>{{ dateText(item.date) }}</small></strong></div><div v-if="!recent.length" class="empty">{{ t('inventory.noOperations') }}</div></q-card><q-card flat class="panel"><div class="panel-head"><div><h2>{{ t('inventory.lowStockProducts') }}</h2><span>{{ t('inventory.belowMinimum') }}</span></div><q-icon name="warning_amber" color="orange-8" size="24px"/></div><div v-for="product in lowStock" :key="product.id" class="stock"><div><b>{{ product.name }}</b><span>{{ product.category }} · {{ product.sku }}</span></div><strong>{{ product.stock }} {{ product.unit }}</strong></div><div v-if="!lowStock.length" class="empty good"><q-icon name="check_circle"/> {{ t('inventory.allStockEnough') }}</div></q-card></div>
      </q-tab-panel>

      <q-tab-panel name="products" class="q-pa-none"><q-card flat class="panel table-panel"><div class="toolbar"><div><h2>{{ t('inventory.catalog') }}</h2><span>{{ filteredProducts.length }} ta mahsulot ko'rsatilmoqda</span></div><q-input v-model="search" dense outlined clearable :placeholder="t('inventory.searchProduct')"><template #prepend><q-icon name="search"/></template></q-input><q-select v-model="categoryFilter" dense outlined emit-value map-options :options="categoryOptions" :label="t('inventory.category')"/><q-btn unelevated no-caps color="primary" icon="add" :label="t('inventory.addProduct')" @click="openProduct"/></div><q-table flat :rows="filteredProducts" :columns="productColumns" row-key="id" hide-pagination :pagination="{rowsPerPage:0}" class="data-table"><template #body-cell-name="props"><q-td :props="props"><div class="product"><span :class="`avatar a${props.row.id%4}`"><q-icon :name="iconFor(props.row.category)"/></span><div><b>{{ props.row.name }}</b><small>{{ props.row.sku }}</small></div></div></q-td></template><template #body-cell-stock="props"><q-td :props="props"><span :class="{warning:props.row.stock<=props.row.minStock}"><b>{{ props.row.stock }}</b> {{ props.row.unit }}</span></q-td></template><template #body-cell-purchase="props"><q-td :props="props">{{ money(props.row.purchasePrice) }}</q-td></template><template #body-cell-sale="props"><q-td :props="props"><b>{{ money(props.row.salePrice) }}</b></q-td></template><template #body-cell-actions="props"><q-td :props="props"><q-btn flat round dense icon="more_horiz"><q-menu><q-list dense><q-item clickable v-close-popup @click="openProduct(props.row)"><q-item-section avatar><q-icon name="edit"/></q-item-section><q-item-section>{{ t('inventory.edit') }}</q-item-section></q-item><q-item clickable v-close-popup @click="openMovement(props.row,'out')"><q-item-section avatar><q-icon name="north_east"/></q-item-section><q-item-section>{{ t('inventory.enterOutflow') }}</q-item-section></q-item></q-list></q-menu></q-btn></q-td></template></q-table></q-card></q-tab-panel>

      <q-tab-panel name="operations" class="q-pa-none"><q-card flat class="panel table-panel"><div class="toolbar"><div><h2>{{ t('inventory.journal') }}</h2><span>{{ t('inventory.allMovements') }}</span></div><q-input v-model="opSearch" dense outlined clearable :placeholder="t('inventory.search')"><template #prepend><q-icon name="search"/></template></q-input><q-btn unelevated no-caps color="primary" icon="add" :label="t('inventory.addOperation')" @click="openMovement"/></div><q-table flat :rows="filteredMovements" :columns="movementColumns" row-key="id" hide-pagination :pagination="{rowsPerPage:0}" class="data-table"><template #body-cell-type="props"><q-td :props="props"><q-chip dense :color="props.row.type==='in'?'green-1':'blue-1'" :text-color="props.row.type==='in'?'positive':'primary'" :icon="props.row.type==='in'?'south_west':'north_east'">{{ props.row.type==='in'?t('inventory.incoming'):t('inventory.outgoing') }}</q-chip></q-td></template><template #body-cell-productId="props"><q-td :props="props"><b>{{ productName(props.row.productId) }}</b></q-td></template><template #body-cell-total="props"><q-td :props="props"><b>{{ money(props.row.quantity*props.row.price) }}</b></q-td></template><template #body-cell-date="props"><q-td :props="props">{{ dateText(props.row.date) }}</q-td></template></q-table></q-card></q-tab-panel>

      <q-tab-panel name="reports" class="q-pa-none"><div class="report-grid"><q-card flat class="report-card"><div class="eyebrow">{{ t('inventory.monthlyReport') }}</div><h2>{{ monthName }} {{ t('inventory.monthResults') }}</h2><strong>{{ money(monthSales) }}</strong><span>{{ t('inventory.turnover') }}</span><div class="report-line"><span>{{ t('inventory.estimatedProfit') }}</span><b>{{ money(monthProfit) }}</b></div><div class="report-line"><span>{{ t('inventory.total') }} sotilgan mahsulot</span><b>{{ monthQty }} {{ t('inventory.dayUnit') }}</b></div></q-card><q-card flat class="panel"><div class="panel-head"><div><h2>{{ t('inventory.dailyResults') }}</h2><span>{{ t('inventory.currentMonth') }}</span></div><q-icon name="calendar_month" color="primary" size="24px"/></div><div v-for="day in reportDays" :key="day.date" class="report-day"><span>{{ dateText(day.date) }}</span><q-linear-progress rounded :value="day.sales / maxSales" color="primary" track-color="grey-3"/><small>{{ money(day.sales) }}</small><b>{{ day.quantity }} {{ t('inventory.dayUnit') }}</b></div></q-card></div></q-tab-panel>
    </q-tab-panels>

    <q-dialog v-model="movementDialog"><q-card class="dialog"><div class="dialog-head"><div><h2>{{ t('inventory.newOperation') }}</h2><span>{{ t('inventory.recordMovement') }}</span></div><q-btn v-close-popup flat round dense icon="close"/></div><q-card-section class="form"><q-btn-toggle v-model="movementForm.type" spread unelevated toggle-color="primary" :options="[{label:t('inventory.incomingShort'),value:'in'},{label:t('inventory.outgoingSale'),value:'out'}]" class="full"/><q-select v-model="movementForm.productId" outlined :label="t('inventory.selectProduct')" :options="productOptions" emit-value map-options/><q-input v-model.number="movementForm.quantity" outlined type="number" :label="t('inventory.quantity') + ' *'" min="1"/><q-input v-model.number="movementForm.price" outlined type="number" :label="t('inventory.unitPrice') + ' *'" prefix="UZS"/><q-input v-model="movementForm.date" outlined type="date" :label="t('inventory.date')"/><q-input v-model="movementForm.note" outlined :label="t('inventory.note')" class="full"/></q-card-section><q-card-actions align="right"><q-btn flat no-caps :label="t('inventory.cancel')" v-close-popup/><q-btn unelevated no-caps color="primary" :label="t('inventory.save')" :disable="!canSaveMovement" @click="saveMovement"/></q-card-actions></q-card></q-dialog>
    <q-dialog v-model="productDialog"><q-card class="dialog"><div class="dialog-head"><div><h2>{{ editingProduct ? t('inventory.editProduct') : t('inventory.newProduct') }}</h2><span>{{ t('inventory.catalogData') }}</span></div><q-btn v-close-popup flat round dense icon="close"/></div><q-card-section class="form"><q-input v-model="productForm.name" outlined :label="t('inventory.productName')" class="full"/><q-input v-model="productForm.sku" outlined :label="t('inventory.sku')"/><q-select v-model="productForm.category" outlined :label="t('inventory.category')" :options="categoryNames"/><q-select v-model="productForm.unit" outlined :label="t('inventory.unit')" :options="['dona','kg','litr','quti']"/><q-input v-model.number="productForm.stock" outlined type="number" label="Boshlang'ich qoldiq"/><q-input v-model.number="productForm.minStock" outlined type="number" :label="t('inventory.minimumStock')"/><q-input v-model.number="productForm.purchasePrice" outlined type="number" :label="t('inventory.purchasePrice')" prefix="UZS"/><q-input v-model.number="productForm.salePrice" outlined type="number" :label="t('inventory.salePrice')" prefix="UZS"/></q-card-section><q-card-actions align="right"><q-btn flat no-caps :label="t('inventory.cancel')" v-close-popup/><q-btn unelevated no-caps color="primary" :label="t('inventory.save')" :disable="!productForm.name || !productForm.sku" @click="saveProduct"/></q-card-actions></q-card></q-dialog>
  </q-page>
</template>

<script setup>
import { computed, ref, watch } from 'vue'
import { useQuasar } from 'quasar'
import { useI18n } from 'src/i18n/index.js'

const $q = useQuasar(); const { t } = useI18n(); const tab = ref('overview'); const search = ref(''); const opSearch = ref(''); const categoryFilter = ref('all'); const movementDialog = ref(false); const productDialog = ref(false); const editingProduct = ref(null)
const today = new Date().toISOString().slice(0, 10); const money = (value) => `${new Intl.NumberFormat('uz-UZ').format(Math.round(value || 0))} UZS`; const compact = (value) => value > 999999 ? `${(value / 1000000).toFixed(1)}M` : `${Math.round(value / 1000)}k`; const dateText = (value) => new Intl.DateTimeFormat('uz-UZ', {day:'2-digit', month:'short'}).format(new Date(value)); const monthName = new Intl.DateTimeFormat('uz-UZ', {month:'long', year:'numeric'}).format(new Date())
const products = ref(load('supermarket-products', [{id:1,name:'Coca-Cola 1.5L',sku:'BEV-001',category:'Ichimliklar',unit:'dona',stock:84,minStock:30,purchasePrice:8500,salePrice:11000},{id:2,name:'Guruch Devzira',sku:'GRN-014',category:'Yorma va don',unit:'kg',stock:18,minStock:25,purchasePrice:28000,salePrice:35000},{id:3,name:'Sut 3.2% 1L',sku:'DRY-021',category:'Sut mahsulotlari',unit:'dona',stock:46,minStock:20,purchasePrice:9000,salePrice:12000},{id:4,name:'Tuxum 10 dona',sku:'DRY-031',category:'Sut mahsulotlari',unit:'quti',stock:12,minStock:15,purchasePrice:18000,salePrice:23000},{id:5,name:"Kungaboqar yog'i 1L",sku:'GRC-008',category:'Oziq-ovqat',unit:'dona',stock:63,minStock:20,purchasePrice:16000,salePrice:21000},{id:6,name:'Non baton',sku:'BAK-003',category:'Non va pishiriq',unit:'dona',stock:31,minStock:25,purchasePrice:3500,salePrice:5000}]))
const movements = ref(load('supermarket-movements', [{id:1,type:'out',productId:1,quantity:24,price:11000,date:today,note:'Kassa 01 sotuvlari'},{id:2,type:'in',productId:3,quantity:60,price:9000,date:today,note:'Fresh Dairy yetkazib berishi'},{id:3,type:'out',productId:5,quantity:16,price:21000,date:today,note:'Kassa 02 sotuvlari'},{id:4,type:'in',productId:2,quantity:40,price:28000,date:today,note:'Agro Trade kirimi'},{id:5,type:'out',productId:4,quantity:8,price:23000,date:new Date(Date.now()-86400000).toISOString().slice(0,10),note:'Kassa 01 sotuvlari'},{id:6,type:'out',productId:6,quantity:21,price:5000,date:new Date(Date.now()-172800000).toISOString().slice(0,10),note:'Kassa 03 sotuvlari'}]))
function load(key, fallback) { try { return JSON.parse(localStorage.getItem(key)) || fallback } catch { return fallback } } watch(products, (value) => localStorage.setItem('supermarket-products', JSON.stringify(value)), {deep:true}); watch(movements, (value) => localStorage.setItem('supermarket-movements', JSON.stringify(value)), {deep:true})
const productColumns = [{name:'name',label:t('inventory.product'),field:'name',align:'left'},{name:'category',label:t('inventory.category'),field:'category',align:'left'},{name:'stock',label:t('inventory.stock'),field:'stock',align:'left'},{name:'purchase',label:t('inventory.purchasePrice'),field:'purchasePrice',align:'left'},{name:'sale',label:t('inventory.salePrice'),field:'salePrice',align:'left'},{name:'actions',label:'',field:'actions',align:'right'}]; const movementColumns = [{name:'type',label:t('inventory.type'),field:'type',align:'left'},{name:'productId',label:t('inventory.product'),field:'productId',align:'left'},{name:'quantity',label:t('inventory.quantity'),field:'quantity',align:'left'},{name:'price',label:t('inventory.unitPrice'),field:'price',format:money,align:'left'},{name:'total',label:t('inventory.total'),field:'total',align:'left'},{name:'date',label:t('inventory.date'),field:'date',align:'left'},{name:'note',label:t('inventory.note'),field:'note',align:'left'}]
const categories = computed(() => [...new Set(products.value.map((p) => p.category))]); const categoryNames = computed(() => [...new Set([...categories.value,'Ichimliklar','Oziq-ovqat'])]); const categoryOptions = computed(() => [{label:t('inventory.allCategories'),value:'all'},...categories.value.map((value) => ({label:value,value}))]); const filteredProducts = computed(() => products.value.filter((p) => (!search.value || `${p.name} ${p.sku}`.toLowerCase().includes(search.value.toLowerCase())) && (categoryFilter.value==='all' || p.category===categoryFilter.value))); const filteredMovements = computed(() => movements.value.filter((m) => !opSearch.value || `${productName(m.productId)} ${m.note || ''}`.toLowerCase().includes(opSearch.value.toLowerCase())).sort((a,b) => new Date(b.date)-new Date(a.date))); const recent = computed(() => filteredMovements.value.slice(0,5)); const lowStock = computed(() => products.value.filter((p) => p.stock <= p.minStock)); const stockValue = computed(() => products.value.reduce((sum,p) => sum+p.stock*p.purchasePrice,0)); const todayMovements = computed(() => movements.value.filter((m) => m.date===today)); const salesToday = computed(() => todayMovements.value.filter((m) => m.type==='out').reduce((sum,m) => sum+m.quantity*m.price,0)); const purchaseToday = computed(() => todayMovements.value.filter((m) => m.type==='in').reduce((sum,m) => sum+m.quantity*m.price,0)); const monthMoves = computed(() => movements.value.filter((m) => m.date.slice(0,7)===today.slice(0,7))); const monthSales = computed(() => monthMoves.value.filter((m) => m.type==='out').reduce((sum,m) => sum+m.quantity*m.price,0)); const monthProfit = computed(() => monthMoves.value.filter((m) => m.type==='out').reduce((sum,m) => sum+m.quantity*(m.price-(products.value.find((p) => p.id===m.productId)?.purchasePrice || 0)),0)); const monthQty = computed(() => monthMoves.value.filter((m) => m.type==='out').reduce((sum,m) => sum+m.quantity,0))
const metricCards = computed(() => [{label:t('inventory.todaySales'),value:money(salesToday.value),icon:'point_of_sale',subIcon:'trending_up',sub:`${todayMovements.value.filter((m)=>m.type==='out').length} ${t('inventory.salesOperations')}`,tone:'blue'},{label:t('inventory.todayPurchase'),value:money(purchaseToday.value),icon:'south_west',subIcon:'inventory_2',sub:`${todayMovements.value.filter((m)=>m.type==='in').length} ${t('inventory.purchaseOperations')}`,tone:'green'},{label:t('inventory.stockValue'),value:money(stockValue.value),icon:'warehouse',subIcon:'layers',sub:`${products.value.length} ${t('inventory.productTypes')}`,tone:'violet'},{label:t('inventory.lowStock'),value:lowStock.value.length,icon:'warning_amber',subIcon:'priority_high',sub:t('inventory.needsAttention'),tone:'orange'}]); const categoryStats = computed(() => { const total=stockValue.value; return categories.value.map((name,i) => ({name,percent:total?Math.round(products.value.filter((p)=>p.category===name).reduce((s,p)=>s+p.stock*p.purchasePrice,0)/total*100):0,color:['#2563eb','#10b981','#f59e0b','#8b5cf6'][i%4],qColor:['primary','positive','orange','deep-purple'][i%4]})) }); const chart = computed(() => { const values=Array.from({length:7},(_,i) => {const date=new Date(Date.now()-(6-i)*86400000).toISOString().slice(0,10); return {date,value:movements.value.filter((m)=>m.type==='out'&&m.date===date).reduce((s,m)=>s+m.quantity*m.price,0)}}); const max=Math.max(...values.map((v)=>v.value),1); return values.map((v)=>({...v,percent:Math.max(v.value/max*100,v.value?5:3),label:new Intl.DateTimeFormat('uz-UZ',{weekday:'short'}).format(new Date(v.date)).replace('.','')})) }); const reportDays = computed(() => [...new Set(monthMoves.value.map((m)=>m.date))].sort().reverse().map((date)=>({date,sales:monthMoves.value.filter((m)=>m.date===date&&m.type==='out').reduce((s,m)=>s+m.quantity*m.price,0),quantity:monthMoves.value.filter((m)=>m.date===date&&m.type==='out').reduce((s,m)=>s+m.quantity,0)}))); const maxSales = computed(() => Math.max(...reportDays.value.map((d)=>d.sales),1)); const productOptions = computed(() => products.value.map((p)=>({label:`${p.name} (${p.stock} ${p.unit})`,value:p.id}))); const canSaveMovement = computed(() => movementForm.value.productId && movementForm.value.quantity>0 && movementForm.value.price>=0)
const movementForm=ref({type:'in',productId:1,quantity:1,price:8500,date:today,note:''}); const productForm=ref({name:'',sku:'',category:'Oziq-ovqat',unit:'dona',stock:0,minStock:10,purchasePrice:0,salePrice:0})
function productName(id){return products.value.find((p)=>p.id===id)?.name || t('inventory.unknownProduct')} function unit(id){return products.value.find((p)=>p.id===id)?.unit || 'dona'} function iconFor(category){return category==='Ichimliklar'?'local_drink':category==='Non va pishiriq'?'bakery_dining':category==='Sut mahsulotlari'?'egg_alt':'shopping_basket'} function openMovement(product=null,type='in'){movementForm.value={type,productId:product?.id||products.value[0]?.id||null,quantity:1,price:type==='out'?(product?.salePrice||products.value[0]?.salePrice||0):(product?.purchasePrice||products.value[0]?.purchasePrice||0),date:today,note:''};movementDialog.value=true} function saveMovement(){const form={...movementForm.value};const product=products.value.find((p)=>p.id===form.productId);if(!product||(form.type==='out'&&form.quantity>product.stock)){ $q.notify({type:'negative',message:t('inventory.outflowError'),position:'top'});return} product.stock+=form.type==='in'?Number(form.quantity):-Number(form.quantity);movements.value.unshift({...form,id:Date.now(),quantity:Number(form.quantity),price:Number(form.price)});movementDialog.value=false;$q.notify({type:'positive',message:t('inventory.operationSaved'),position:'top'})} function openProduct(product=null){editingProduct.value=product;productForm.value=product?{...product}:{name:'',sku:`SKU-${String(Date.now()).slice(-4)}`,category:categoryNames.value[0]||'Oziq-ovqat',unit:'dona',stock:0,minStock:10,purchasePrice:0,salePrice:0};productDialog.value=true} function saveProduct(){if(editingProduct.value)Object.assign(editingProduct.value,productForm.value);else products.value.push({...productForm.value,id:Date.now()});productDialog.value=false;$q.notify({type:'positive',message:editingProduct.value?t('inventory.productUpdated'):t('inventory.productAdded'),position:'top'})} function exportReport(){const rows=[['inventory.product','inventory.sku','inventory.category','inventory.stock','inventory.purchasePrice','inventory.salePrice'].map((key) => t(key)).join(','),...products.value.map((p)=>[p.name,p.sku,p.category,p.stock,p.purchasePrice,p.salePrice].join(','))];const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([rows.join('\n')],{type:'text/csv'}));link.download=`ombor-${today}.csv`;link.click()}
